<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{Container,Csrf,Database,Request,Response,Session,View};
use App\Repositories\AdmissionsRepository;
use App\Services\AccessService;
final class AdmissionsController
{
 private function repo():AdmissionsRepository{return new AdmissionsRepository(Container::get(Database::class)->connection());}
 private function actor():int{return (int)Session::get('auth_user')['id'];}
 private function csrf(Request $r):void{if(!Csrf::validate((string)$r->input('_csrf')))Response::abort(419,'CSRF inválido.');}
 public function index(Request $r):void{AccessService::require('admisiones.solicitudes.ver');$q=trim((string)$r->input('q',''));$st=trim((string)$r->input('estado',''));View::render('admin/admisiones/index',['title'=>'Admisiones','applications'=>$this->repo()->applications($q,$st),'q'=>$q,'status'=>$st]);}
 public function form(Request $r):void{AccessService::require('admisiones.solicitudes.crear');$x=$this->repo();View::render('admin/admisiones/form',['title'=>'Nueva admisión','types'=>$x->identificationTypes(),'channels'=>$x->channels(),'entryTypes'=>$x->entryTypes(),'careers'=>$x->careers(),'campuses'=>$x->campuses(),'modalities'=>$x->modalities()]);}
 public function save(Request $r):never{$this->csrf($r);AccessService::require('admisiones.solicitudes.crear');$d=['tipo_identificacion_id'=>(int)$r->input('tipo_identificacion_id'),'numero_identificacion'=>trim((string)$r->input('numero_identificacion')),'primer_nombre'=>trim((string)$r->input('primer_nombre')),'segundo_nombre'=>trim((string)$r->input('segundo_nombre')),'primer_apellido'=>trim((string)$r->input('primer_apellido')),'segundo_apellido'=>trim((string)$r->input('segundo_apellido')),'canal_admision_id'=>(int)$r->input('canal_admision_id'),'tipo_ingreso_id'=>(int)$r->input('tipo_ingreso_id'),'carrera_id'=>(int)$r->input('carrera_id'),'sede_id'=>(int)$r->input('sede_id'),'modalidad_id'=>(int)$r->input('modalidad_id'),'observacion'=>trim((string)$r->input('observacion'))];if(!$d['tipo_identificacion_id']||$d['numero_identificacion']===''||$d['primer_nombre']===''||$d['primer_apellido']===''||!$d['tipo_ingreso_id']||!$d['carrera_id'])Response::abort(422,'Completa identificación, nombres, tipo de ingreso y carrera.');$id=$this->repo()->createApplication($d,$this->actor());Response::redirect('/admin/admisiones/solicitud?id='.$id);}
 public function show(Request $r):void{AccessService::require('admisiones.solicitudes.ver');$id=(int)$r->input('id');$x=$this->repo();$a=$x->application($id);if(!$a)Response::abort(404,'Solicitud no encontrada.');View::render('admin/admisiones/show',['title'=>$a['numero_solicitud'],'application'=>$a,'history'=>$x->applicationHistory($id)]);}
 public function review(Request $r):never{$this->csrf($r);AccessService::require('admisiones.solicitudes.editar');$id=(int)$r->input('id');$this->repo()->setReview($id,$this->actor());Response::redirect('/admin/admisiones/solicitud?id='.$id);}
 public function approve(Request $r):never{$this->csrf($r);AccessService::require('admisiones.solicitudes.aprobar');$id=(int)$r->input('id');$student=$this->repo()->approve($id,$this->actor());Response::redirect('/admin/estudiantes/ver?id='.$student);}
 public function reject(Request $r):never{$this->csrf($r);AccessService::require('admisiones.solicitudes.rechazar');$id=(int)$r->input('id');$this->repo()->reject($id,$this->actor(),trim((string)$r->input('motivo')));Response::redirect('/admin/admisiones/solicitud?id='.$id);}
 public function students(Request $r):void{AccessService::require('estudiantes.ver');$q=trim((string)$r->input('q',''));View::render('admin/estudiantes/index',['title'=>'Estudiantes','students'=>$this->repo()->students($q),'q'=>$q]);}
 public function student(Request $r):void{AccessService::require('estudiantes.ver');$id=(int)$r->input('id');$x=$this->repo();$s=$x->student($id);if(!$s)Response::abort(404,'Estudiante no encontrado.');View::render('admin/estudiantes/show',['title'=>$s['nombre'],'student'=>$s,'contacts'=>$x->contacts($id),'socio'=>$x->socio($id),'socioHistory'=>$x->socioHistory($id),'contactTypes'=>$x->contactTypes(),'occupations'=>$x->occupations(),'financing'=>$x->financing(),'familyEducation'=>$x->familyEducation(),'schoolTypes'=>$x->schoolTypes()]);}
 public function contactSave(Request $r):never{$this->csrf($r);AccessService::require('estudiantes.editar');$id=(int)$r->input('estudiante_id');$d=['tipo'=>(int)$r->input('tipo_contacto_id'),'nombres'=>trim((string)$r->input('nombres')),'apellidos'=>trim((string)$r->input('apellidos')),'parentesco'=>trim((string)$r->input('parentesco')),'telefono'=>trim((string)$r->input('telefono')),'correo'=>trim((string)$r->input('correo')),'direccion'=>trim((string)$r->input('direccion')),'principal'=>(bool)$r->input('es_principal')];if(!$d['tipo']||$d['nombres']==='')Response::abort(422,'Tipo y nombres del contacto son obligatorios.');$this->repo()->addContact($id,$d);Response::redirect('/admin/estudiantes/ver?id='.$id);}
 public function socioSave(Request $r):never{$this->csrf($r);AccessService::require('estudiantes.editar');$id=(int)$r->input('estudiante_id');$d=['ocupacion'=>(int)$r->input('ocupacion_id'),'financiamiento'=>(int)$r->input('financiamiento_id'),'bono'=>$r->input('recibe_bono')!==null?1:0,'nivel_padre'=>(int)$r->input('nivel_padre_id'),'nivel_madre'=>(int)$r->input('nivel_madre_id'),'ingresos'=>trim((string)$r->input('ingresos_hogar')),'miembros'=>(int)$r->input('miembros_hogar'),'tipo_colegio'=>(int)$r->input('tipo_colegio_id'),'ayuda'=>$r->input('tiene_ayuda')!==null?1:0,'valor_ayuda'=>trim((string)$r->input('valor_ayuda'))];$this->repo()->saveSocio($id,$d,$this->actor());Response::redirect('/admin/estudiantes/ver?id='.$id);}
}
